type agreementCanonicalDiagnosticOwner struct {
	Field  int
	Family string
	Code   agreementNativeCodeDiagnosticOwner
	Native agreementMixedUnusedOwner
	HTML   agreementHTMLDiagnosticOwner
}

// Native discarded fields keep one footnote declaration even when both readers name it.
func agreementCanonicalDiagnosticNativeOwners(native agreementNativeOwnerSource, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementMixedUnusedOwner, bool) {
	var owners []agreementMixedUnusedOwner
	if !tree.Valid {
		return nil, false
	}
	used := make(map[graph.Span]bool)
	for fi, field := range check.Fields {
		if field.Comment || field.Escaped || field.DefinitionOwner < 0 || !slices.Contains(field.Targets, target) {
			continue
		}
		if len(field.Targets) != 1 || field.DefinitionOwner >= len(native.Definitions) || used[field.Span] {
			return nil, false
		}
		definition := &native.Definitions[field.DefinitionOwner]
		if definition.Span.Start < 0 || definition.Span.Stop <= definition.Span.Start || field.Span.Start < definition.Span.Start || field.Span.Stop > definition.Span.Stop || field.Span.Stop <= field.Span.Start || definition.Name.Start < definition.Span.Start || definition.Name.Stop > definition.Span.Stop {
			return nil, false
		}
		candidate := -1
		for di := range tree.Definitions {
			d := &tree.Definitions[di]
			if !d.Found || d.Root != field.DefinitionOwner+1 || d.Root >= len(tree.Trees) || d.Root < 1 || d.Node != 0 || len(tree.Trees[d.Root]) == 0 || tree.Trees[d.Root][0].Kind != extast.KindFootnote.String() || d.Label != definition.Label || d.Bounds.Parent != definition.Parent || d.Bounds.Span != definition.Span || d.Bounds.Label != definition.Name {
				continue
			}
			if candidate >= 0 {
				return nil, false
			}
			candidate = di
		}
		if candidate < 0 {
			return nil, false
		}
		used[field.Span] = true
		d := &tree.Definitions[candidate]
		owners = append(owners, agreementMixedUnusedOwner{Field: fi, Definition: field.DefinitionOwner, Root: d.Root, Node: d.Node})
	}
	return owners, len(owners) > 0
}

func agreementCanonicalDiagnosticPhysical(body string, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementCanonicalDiagnosticOwner, bool) {
	if (target != "A" && target != "q") || !tree.Valid {
		return nil, false
	}
	native := agreementNativeOwnerReading(body)
	code, cok := agreementNativeCodeDiagnosticPhysical(native, check, target)
	discarded, dok := agreementCanonicalDiagnosticNativeOwners(native, check, tree, target)
	html, hok := agreementHTMLDiagnosticPhysical(body, check, agreementNativeHTMLAddressSites(body), tree, target)
	if !cok && !dok && !hok {
		return nil, false
	}
	byField := map[int]agreementCanonicalDiagnosticOwner{}
	if cok {
		for _, o := range code {
			byField[o.Field] = agreementCanonicalDiagnosticOwner{Field: o.Field, Family: "native-code", Code: o}
		}
	}
	if dok {
		for _, o := range discarded {
			if _, seen := byField[o.Field]; seen {
				return nil, false
			}
			byField[o.Field] = agreementCanonicalDiagnosticOwner{Field: o.Field, Family: "native-discarded", Native: o}
		}
	}
	if hok {
		for _, o := range html {
			if _, seen := byField[o.Field]; seen {
				return nil, false
			}
			byField[o.Field] = agreementCanonicalDiagnosticOwner{Field: o.Field, Family: "html", HTML: o}
		}
	}
	var owners []agreementCanonicalDiagnosticOwner
	for fi := range check.Fields {
		if o, ok := byField[fi]; ok {
			f := check.Fields[fi]
			if len(f.Targets) != 1 || f.Targets[0] != target || f.Comment || f.Escaped {
				return nil, false
			}
			owners = append(owners, o)
		}
	}
	return owners, len(owners) > 0
}

// A private rename retains every unselected physical field.
func agreementCanonicalDiagnosticPrivate(body, target string, owners []agreementCanonicalDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	if target == "" || len(owners) == 0 || strings.Contains(body, "q") {
		return "", nil, false
	}
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementCanonicalDiagnosticPhysical(body, check, &tree, target)
	if !ok {
		return "", nil, false
	}
	private := []byte(body)
	seen := map[int]bool{}
	var changes []agreementMixedRename
	for oi := range owners {
		o := &owners[oi]
		if o.Field < 0 || o.Field >= len(check.Fields) || seen[o.Field] || !slices.Contains(physical, *o) {
			return "", nil, false
		}
		seen[o.Field] = true
		f := check.Fields[o.Field]
		if f.Span.Start < 0 || f.Span.Stop > len(body) || f.Span.Stop <= f.Span.Start || body[f.Span.Start:f.Span.Stop] != f.Word || !strings.HasPrefix(f.Word, "[[") || !strings.HasSuffix(f.Word, "]]") {
			return "", nil, false
		}
		inner := f.Word[2 : len(f.Word)-2]
		link, valid := graph.ParseWikilink(inner)
		if !valid || link.Target != target || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) {
			return "", nil, false
		}
		start := f.Span.Start + 2 + strings.Index(inner, target)
		stop := start + len(target)
		if start < f.Span.Start+2 || stop > f.Span.Stop-2 || body[start:stop] != target {
			return "", nil, false
		}
		replacement := strings.Repeat("q", len(target))
		copy(private[start:stop], replacement)
		changes = append(changes, agreementMixedRename{Field: o.Field, Span: graph.Span{Start: start, Stop: stop}, Old: target, New: replacement})
	}
	return string(private), changes, true
}

// A code-only producer moves a diagnostic without adding a check citation.
func agreementCanonicalDiagnosticActive(owners []agreementCanonicalDiagnosticOwner, check *agreementNativeCheckSource) int {
	count := 0
	for oi := range owners {
		o := &owners[oi]
		if o.Field < 0 || o.Field >= len(check.Fields) {
			return -1
		}
		if !check.Fields[o.Field].Code {
			count++
		}
	}
	return count
}

func agreementCanonicalDiagnosticProducers(t *testing.T, body, target string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) (physicalFields, diagnosticFields []agreementCanonicalDiagnosticOwner, targetChanges []agreementMixedRename, projectedBody string, valid bool) {
	t.Helper()
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementCanonicalDiagnosticPhysical(body, check, &tree, target)
	if !ok {
		return nil, nil, nil, "", false
	}
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	parts, pok := agreementCodeWindowParts(raw.HTML)
	if !pok {
		return nil, nil, nil, "", false
	}
	var owners []agreementCanonicalDiagnosticOwner
	var changes []agreementMixedRename
	whole := []byte(body)
	used := map[int]bool{}
	for oi := range physical {
		owner := &physical[oi]
		private, oneChanges, valid := agreementCanonicalDiagnosticPrivate(body, target, []agreementCanonicalDiagnosticOwner{*owner}, check)
		if !valid {
			continue
		}
		pr, pp := agreementIsolatedPage(t, agreementCase{Body: private})
		privateParts, validParts := agreementCodeWindowParts(pr.HTML)
		if !validParts || !cmp.Equal(native, agreementNativeOwnerReading(private)) || !cmp.Equal(tree, agreementNativeProseAddressTreeReading(private, nil)) || raw.HTML != pr.HTML || !cmp.Equal(page, pp) || !cmp.Equal(parts, privateParts) || len(raw.Diagnostics) != len(pr.Diagnostics) {
			continue
		}
		index := -1
		unique := true
		for di := range raw.Diagnostics {
			if cmp.Equal(raw.Diagnostics[di], pr.Diagnostics[di]) {
				continue
			}
			if index >= 0 {
				unique = false
				break
			}
			index = di
		}
		if !unique || index < 0 || used[index] {
			continue
		}
		a, b := raw.Diagnostics[index], pr.Diagnostics[index]
		change := oneChanges[0]
		if a.Section != "" || a.Kind != render.DiagWikilinkBroken || a.Target != target || b.Target != change.New || a.Kind != b.Kind || a.Section != b.Section || a.Block != b.Block || b.Message != strings.ReplaceAll(a.Message, "\""+target+"\"", "\""+change.New+"\"") {
			continue
		}
		used[index] = true
		owners = append(owners, *owner)
		changes = append(changes, change)
		copy(whole[change.Span.Start:change.Span.Stop], change.New)
	}
	return physical, owners, changes, string(whole), len(owners) > 0
}

// A diagnostic moves with its physical target while public faces stay fixed.
func agreementCanonicalDiagnosticSignedProjection(before, after []agreementFailure, page *agreementHTML, targets []string, selected *agreementFailure, fields, active int) bool {
	if selected == nil || fields < 1 || active < 1 || active > fields || fields != selected.Multiplicity || selected.Tuple.Target == "" {
		return false
	}
	target := selected.Tuple.Target
	replacement := strings.Repeat("q", len(target))
	counts := map[string]int{}
	for _, name := range targets {
		counts[name]++
	}
	visible := map[string]int{}
	for _, citation := range page.Citations {
		if citation.SourceRole == "" && citation.Target != "" {
			visible[citation.Target]++
		}
	}
	if counts[target] < active || counts[replacement] != 0 || visible[replacement] != 0 {
		return false
	}
	signed := func(name string, delta int) string {
		if delta == 0 {
			return ""
		}
		direction := "judge-only"
		if delta < 0 {
			direction = "page-only"
			delta = -delta
		}
		f := agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: name}, Direction: direction, Multiplicity: delta}
		return agreementSignature(&f)
	}
	oldP1 := map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property == "P1" && (f.Tuple.Target == target || f.Tuple.Target == replacement) {
			oldP1[agreementSignature(f)]++
		}
	}
	declared := map[string]int{}
	if signature := signed(target, counts[target]-visible[target]); signature != "" {
		declared[signature] = 1
	}
	if !maps.Equal(oldP1, declared) {
		return false
	}
	expected := maps.Clone(agreementMixedCurrent(before))
	signature := agreementSignature(selected)
	if expected[signature] != 1 {
		return false
	}
	delete(expected, signature)
	renamed := *selected
	renamed.Tuple.Target = replacement
	expected[agreementSignature(&renamed)]++
	for key := range oldP1 {
		delete(expected, key)
	}
	if key := signed(target, counts[target]-active-visible[target]); key != "" {
		expected[key]++
	}
	expected[signed(replacement, active)]++
	return maps.Equal(expected, agreementMixedCurrent(after))
}

func agreementCanonicalDiagnosticSource(body, target string) (*agreementCanonicalDiagnosticSourceWitness, *agreementCanonicalDiagnosticVariant, bool) {
	witnesses := agreementCanonicalDiagnosticSources()
	for wi := range witnesses {
		w := &witnesses[wi]
		if w.Body != body {
			continue
		}
		for vi := range w.Variants {
			v := &w.Variants[vi]
			if v.Target == target {
				return w, v, true
			}
		}
		return nil, nil, false
	}
	return nil, nil, false
}

// Every changed diagnostic belongs to one declared native code, HTML or discarded footnote field.
func agreementCanonicalDiagnosticDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P0" || f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementCanonicalDiagnosticWitnesses()
	for ri := range records {
		r := &records[ri]
		if c.Body != r.Body || f.Tuple.Target != r.Target {
			continue
		}
		if agreementSignature(f) != r.Selected || !cmp.Equal(diagnostics, r.Diagnostics) {
			return "", "", ""
		}
		w, v, found := agreementCanonicalDiagnosticSource(c.Body, r.Target)
		if !found {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		physical, ok := agreementCanonicalDiagnosticPhysical(c.Body, &check, &tree, r.Target)
		private, changes, valid := agreementCanonicalDiagnosticPrivate(c.Body, r.Target, v.Owners, &check)
		if !pok || !ok || !valid || len(v.Owners) != f.Multiplicity || len(r.Indices) != len(v.Owners) || !cmp.Equal(physical, v.Physical) || !cmp.Equal(changes, v.Changes) || private != v.Body || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementRemovedCommentDiagnosticRead(c.Body), w.Removed) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

